def _compute_validate_button_style(self):
    for picking in self:
        if picking.state in ('done', 'cancel'):
            picking.validate_button_style = 'invisible'
        elif picking.state in ('waiting', 'assigned'):
            picking.validate_button_style = 'primary'
        else:
            picking.validate_button_style = 'secondary'

def action_confirm(self):
    self._check_company()
    if not self.env.context.get('skip_zero_demand_check') and not modules.module.current_test:
        # Check for zero demand moves before confirming
        zero_demand_moves = self.move_ids.filtered(lambda m: m.product_uom_qty <= 0)
        if zero_demand_moves:
            return self._action_generate_zero_demand_wizard()

    # call `_action_confirm` on every draft move
    self.move_ids.filtered(lambda move: move.state == 'draft')._action_confirm()

    # run scheduler for moves forecasted to not have enough in stock
    self.move_ids.filtered(lambda move: move.state not in ('draft', 'cancel', 'done'))._trigger_scheduler()

    if self.env.user.has_group('stock.group_stock_picking_batch'):
        for picking in self:
            picking._find_auto_batch()
    return True

def action_cancel(self):
    self.move_ids._action_cancel()
    self.write({'is_locked': True})
    self.filtered(lambda x: not x.move_ids).state = 'cancel'
    # Remove the cancelled operation from its batch if the batch has other active picking(s).
    for picking in self:
        if picking.batch_id and any(picking.state != 'cancel' for picking in picking.batch_id.picking_ids):
            picking.batch_id = None
    return True

def _send_confirmation_email(self):
    subtype_id = self.env['ir.model.data']._xmlid_to_res_id('mail.mt_comment')
    for stock_pick in self.filtered(lambda p: p.company_id.stock_move_email_validation and p.picking_type_id.code == 'outgoing'):
        delivery_template = stock_pick.company_id.stock_mail_confirmation_template_id
        stock_pick.with_context(force_send=True).message_post_with_source(
            delivery_template,
            email_layout_xmlid='mail.mail_notification_light',
            subtype_id=subtype_id,
        )

def button_validate(self):
    self = self.filtered(lambda p: p.state != 'done')
    draft_picking = self.filtered(lambda p: p.state == 'draft')
    res = draft_picking.with_context(to_validate=True).action_confirm()
    if res is not True:
        return res
    for move in draft_picking.move_ids:
        if move.uom_id.is_zero(move.quantity) and not move.uom_id.is_zero(move.product_uom_qty):
            move.quantity = move.product_uom_qty

    # Sanity checks.
    if not self.env.context.get('skip_sanity_check', False):
        self._sanity_check()

    # Run the pre-validation wizards. Processing a pre-validation wizard should work on the
    # moves and/or the context and never call `_action_done`.
    if not self.env.context.get('button_validate_picking_ids'):
        self = self.with_context(button_validate_picking_ids=self.ids)
    res = self._pre_action_done_hook()
    if res is not True:
        return res

    # Call `_action_done`.
    pickings_not_to_backorder = self.filtered(lambda p: p.picking_type_id.create_backorder == 'never')
    if self.env.context.get('picking_ids_not_to_backorder'):
        pickings_not_to_backorder |= self.browse(self.env.context['picking_ids_not_to_backorder']).filtered(
            lambda p: p.picking_type_id.create_backorder != 'always'
        )
    pickings_to_backorder = self - pickings_not_to_backorder
    if pickings_not_to_backorder:
        pickings_not_to_backorder.with_context(cancel_backorder=True)._action_done()
    if pickings_to_backorder:
        pickings_to_backorder.with_context(cancel_backorder=False)._action_done()

    # Remove done pickings from their batch.
    if any(picking.state == 'done' for picking in self):
        to_assign_ids = set()
        if self and self.env.context.get('pickings_to_detach'):
            pickings_to_detach = self.env['stock.picking'].browse(self.env.context['pickings_to_detach'])
            pickings_to_detach.batch_id = False
            pickings_to_detach.move_ids.filtered(lambda m: not m.quantity).picked = False
            to_assign_ids.update(self.env.context['pickings_to_detach'])

        for picking in self:
            if picking.state != 'done':
                continue
            # Avoid inconsistencies in states of the same batch when validating a single picking in a batch.
            if picking.batch_id and any(p.state != 'done' for p in picking.batch_id.picking_ids):
                picking.batch_id = None
            # If backorder were made and auto-batch is enabled, seek a batch for each of them with the selected criterias.
            to_assign_ids.update(picking.backorder_ids.ids)

        # If batch setting is enabled, auto-batch done pickings' backorders.
        if self.env.user.has_group('stock.group_stock_picking_batch'):
            # To avoid inconsistencies, all incorrect pickings must be removed before assigning backorder pickings
            assignable_pickings = self.env['stock.picking'].browse(to_assign_ids)
            for picking in assignable_pickings:
                picking._find_auto_batch()
            assignable_pickings.move_line_ids.with_context(skip_auto_waveable=True)._auto_wave()

    report_actions = self._get_autoprint_report_actions()
    if report_actions:
        return {
            'type': 'ir.actions.client',
            'tag': 'do_multi_print',
            'params': {
                'reports': report_actions,
            }
        }
    return True

def _pre_action_done_hook(self):
    for picking in self:
        has_quantity = False
        has_pick = False
        for move in picking.move_ids:
            if move.quantity:
                has_quantity = True
            if move.location_dest_usage == 'inventory':
                continue
            if move.picked:
                has_pick = True
            if has_quantity and has_pick:
                break
        if has_quantity and not has_pick:
            picking.move_ids.picked = True
    if not self.env.context.get('skip_backorder'):
        pickings_to_backorder = self._check_backorder()
        if pickings_to_backorder:
            return pickings_to_backorder._action_generate_backorder_wizard(show_transfers=self._should_show_transfers())
    return True

def _autoconfirm_picking(self):
    """ Automatically run `action_confirm` on `self` if one of the
    picking's move was added after the initial
    call to `action_confirm`. Note that `action_confirm` will only work on draft moves.
    """
    for picking in self:
        if picking.state in ('done', 'cancel'):
            continue
        if not picking.move_ids:
            continue
        if any(move.additional for move in picking.move_ids):
            picking.with_context(skip_zero_demand_check=True).action_confirm()
    to_confirm = self.move_ids.filtered(lambda m: m.state == 'draft' and m.quantity)
    to_confirm._action_confirm()

def assign_batch_user(self, user_id):
    pickings = self.filtered(lambda p: p.user_id.id != user_id)
    pickings.write({'user_id': user_id})
    for pick in pickings:
        if user_id:
            log_message = _('Assigned to %s Responsible', pick.batch_id._get_html_link())
        else:
            log_message = _('Unassigned responsible from %s', pick.batch_id._get_html_link())
        pick.message_post(body=log_message)

def assign_ignore(cls, shipments, moves=None):
    pool = Pool()
    Move = pool.get('stock.move')
    assign_moves = {
        m for s in shipments for m in s.assign_moves
        if m.assignation_required and m.state in {'staging', 'draft'}}
    if moves is None:
        moves = list(assign_moves)
    else:
        moves = [m for m in moves if m in assign_moves]
    Move.write(moves, {
            'quantity': 0,
            })
    with cls.bulk_func('assign', auto=False) as assign:
        for shipment in shipments:
            if all(
                    m.state not in {'staging', 'draft'}
                    for m in shipment.assign_moves
                    if m.assignation_required):
                assign.push(shipment)

def get_partially_assigned(self, name):
    return (self.state != 'assigned'
        and any(m.state == 'assigned' for m in self.assign_moves
            if m.assignation_required))

def search_partially_assigned(cls, name, clause):
    operators = {
        '=': 'where',
        '!=': 'not where',
        }
    reverse = {
        '=': '!=',
        '!=': '=',
        }
    if clause[1] in operators:
        if not clause[2]:
            operator = reverse[clause[1]]
        else:
            operator = clause[1]
        return [
            (cls._assign_moves_field, operators[operator], [
                    ('state', '=', 'assigned'),
                    ('assignation_required', '=', True),
                    ]),
            ('state', '=', 'waiting'),
            ]
    else:
        return []

def preprocess_values(cls, mode, values):
    pool = Pool()
    Configuration = pool.get('stock.configuration')
    values = super().preprocess_values(mode, values)
    if mode == 'create' and not values.get('number'):
        company_id = values.get('company', cls.default_company())
        if company_id is not None:
            configuration = Configuration(1)
            if sequence := configuration.get_multivalue(
                    'shipment_in_sequence', company=company_id):
                values['number'] = sequence.get()
    return values

def create_inventory_moves(cls, shipments):
    for shipment in shipments:
        if shipment.warehouse_storage == shipment.warehouse_input:
            # Do not create inventory moves
            continue
        # Use moves instead of inventory_moves because save reset before
        # adding new records and as set_inventory_moves is just a proxy to
        # moves, it will reset also the incoming_moves
        moves = list(shipment.moves)
        for incoming_move in shipment.incoming_moves:
            move = shipment._get_inventory_move(incoming_move)
            if move:
                moves.append(move)
        shipment.moves = moves
    cls.save(shipments)

def cancel(cls, shipments):
    Move = Pool().get('stock.move')
    Move.cancel([m for s in shipments
            for m in s.incoming_moves + s.inventory_moves])

def assign(cls, shipments):
    Move = Pool().get('stock.move')
    Move.assign([m for s in shipments for m in s.assign_moves])

def cancel(cls, shipments):
    Move = Pool().get('stock.move')
    Move.cancel([m for s in shipments for m in s.moves])

def assign_try(cls, shipments, with_childs=None):
    pool = Pool()
    Move = pool.get('stock.move')
    shipments = [s for s in shipments if s.state == 'waiting']
    to_assign = defaultdict(list)
    for shipment in shipments:
        location_type = shipment.from_location.type
        for move in shipment.assign_moves:
            if move.assignation_required:
                to_assign[location_type].append(move)
    success = True
    for location_type, moves in to_assign.items():
        if with_childs is None:
            _with_childs = location_type == 'view'
        elif not with_childs and location_type == 'view':
            _with_childs = True
        else:
            _with_childs = with_childs
        if not Move.assign_try(moves, with_childs=_with_childs):
            success = False
    if success:
        cls.assign(shipments)
    else:
        with cls.bulk_func('assign', auto=False) as assign:
            for shipment in shipments:
                if any(
                        m.state in {'staging', 'draft'}
                        for m in shipment.assign_moves
                        if m.assignation_required):
                    continue
                assign.push(shipment)

def cancel(cls, shipments):
    Move = Pool().get('stock.move')
    Move.cancel([m for s in shipments
            for m in s.outgoing_moves + s.inventory_moves])

def assign_moves(self):
    if self.warehouse_storage != self.warehouse_output:
        return self.inventory_moves
    else:
        return self.outgoing_moves

def assign_try(cls, shipments):
