def transition_start(self):
    self.record.assign_try()
    if self.record.state == 'assigned':
        return 'end'
    else:
        return 'partial'

def transition_cancel(self):
    self.record.assign_reset()
    return 'end'

def transition_force(self):
    self.record.assign_force()
    return 'end'

def transition_ignore(self):
    self.record.assign_ignore(self.partial.moves)
    return 'end'

@Override
public StockMove createStockMove(
    Address fromAddress,
    Address toAddress,
    Company company,
    Partner clientPartner,
    StockLocation fromStockLocation,
    StockLocation toStockLocation,
    LocalDate realDate,
    LocalDate estimatedDate,
    String note,
    ShipmentMode shipmentMode,
    FreightCarrierMode freightCarrierMode,
    Partner carrierPartner,
    Partner forwarderPartner,
    Incoterm incoterm,
    int typeSelect)
    throws AxelorException {

  StockMove stockMove =
      this.createStockMove(
          fromAddress,
          toAddress,
          company,
          fromStockLocation,
          toStockLocation,
          realDate,
          estimatedDate,
          note,
          typeSelect);
  stockMove.setPartner(clientPartner);
  stockMove.setShipmentMode(shipmentMode);
  stockMove.setFreightCarrierMode(freightCarrierMode);
  stockMove.setCarrierPartner(carrierPartner);
  stockMove.setForwarderPartner(forwarderPartner);
  if (appStockService.getAppStock().getIsIncotermEnabled()) {
    stockMove.setIncoterm(incoterm);
  }
  stockMove.setNote(note);
  stockMove.setIsIspmRequired(stockMoveToolService.getDefaultISPM(clientPartner, toAddress));

  return stockMove;
}

@Override
public StockMove createStockMove(
    Address fromAddress,
    Address toAddress,
    Company company,
    StockLocation fromStockLocation,
    StockLocation toStockLocation,
    LocalDate realDate,
    LocalDate estimatedDate,
    String note,
    int typeSelect)
    throws AxelorException {

  StockMove stockMove = new StockMove();

  if (stockMove.getStockMoveLineList() == null) {
    stockMove.setStockMoveLineList(new ArrayList<>());
  }

  stockMove.setFromAddress(fromAddress);
  stockMove.setToAddress(toAddress);
  stockMoveToolService.computeAddressStr(stockMove);
  stockMove.setCompany(company);
  stockMove.setStatusSelect(StockMoveRepository.STATUS_DRAFT);
  stockMove.setRealDate(realDate);
  stockMove.setEstimatedDate(estimatedDate);
  stockMove.setFromStockLocation(fromStockLocation);
  stockMove.setToStockLocation(toStockLocation);
  stockMove.setNote(note);
  stockMove.setPrintingSettings(
      Beans.get(TradingNameService.class).getDefaultPrintingSettings(null, company));

  stockMove.setTypeSelect(typeSelect);
  stockMove.setIsWithBackorder(company.getStockConfig().getIsWithBackorder());
  if (typeSelect == StockMoveRepository.TYPE_INCOMING) {
    stockMove.setIsWithReturnSurplus(company.getStockConfig().getIsWithReturnSurplus());
  }
  return stockMove;
}

@Override
public StockMove createStockMoveMobility(
    StockLocation fromStockLocation,
    StockLocation toStockLocation,
    Company company,
    List<StockMoveLine> stockMoveLines)
    throws AxelorException {

  StockMove stockMove = createStockMoveMobility(fromStockLocation, toStockLocation, company);
  this.plan(stockMove);
  if (stockMoveLines != null) {
    for (StockMoveLine stockMoveLine : stockMoveLines) {
      // This method will already set sml.stockMove = stockMove so no need to add in list.
      createStockMoveLine(stockMove, stockMoveLine);
    }
  }

  this.realize(stockMove);

  return stockMove;
}

@Transactional(rollbackOn = {Exception.class})
protected StockMove createStockMoveMobility(
    StockLocation fromStockLocation, StockLocation toStockLocation, Company company) {
  StockMove stockMove = new StockMove();
  stockMove.setStatusSelect(StockMoveRepository.STATUS_DRAFT);
  stockMove.setTypeSelect(StockMoveRepository.TYPE_INTERNAL);
  stockMove.setCompany(company);
  stockMove.setFromStockLocation(fromStockLocation);
  stockMove.setFromAddress(fromStockLocation.getAddress());
  stockMove.setToStockLocation(toStockLocation);
  stockMove.setToAddress(toStockLocation.getAddress());
  stockMove.setNote(""); // comment to display on stock move
  stockMove.setPickingOrderComments(""); // comment to display on picking order
  stockMove.setRealDate(LocalDate.now());
  stockMove.setEstimatedDate(LocalDate.now());
  return stockMoveRepo.save(stockMove);
}

@Transactional(rollbackOn = {Exception.class})
protected StockMoveLine createStockMoveLine(StockMove stockMove, StockMoveLine stockMoveLine)
    throws AxelorException {

  Product product = stockMoveLine.getProduct();
  stockMoveLineService.setProductInfo(stockMove, stockMoveLine, stockMove.getCompany());

  TrackingNumberConfiguration trackingNumberConfiguration =
      (TrackingNumberConfiguration)
          productCompanyService.get(
              product, "trackingNumberConfiguration", stockMove.getCompany());
  if (trackingNumberConfiguration != null) {
    stockMoveLine.setTrackingNumber(stockMoveLine.getTrackingNumber());
  }

  if (stockMoveLine.getToStockLocation() == null) {
    stockMoveLine.setToStockLocation(stockMove.getToStockLocation());
  }

  if (stockMoveLine.getFromStockLocation() == null) {
    stockMoveLine.setFromStockLocation(stockMove.getFromStockLocation());
  }

  stockMoveLine.setIsRealQtyModifiedByUser(true);
  stockMoveLine.setUnitPriceUntaxed(product.getLastPurchasePrice());
  stockMove.addStockMoveLineListItem(stockMoveLine);
  stockMoveLineRepo.save(stockMoveLine);
  stockMoveLineService.setAvailableStatus(stockMoveLine, stockMove);
  stockMoveLineService.compute(stockMoveLine, stockMove);
  return stockMoveLineRepo.save(stockMoveLine);
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void validate(StockMove stockMove) throws AxelorException {

  this.plan(stockMove);
  this.realize(stockMove);
}

protected void setPlannedStatus(StockMove stockMove) {
  stockMove.setStatusSelect(StockMoveRepository.STATUS_PLANNED);
  stockMoveRepo.save(stockMove);
}

protected void setRealizedStatus(StockMove stockMove) {
  stockMove.setStatusSelect(StockMoveRepository.STATUS_REALIZED);
}

public void sendSupplierCancellationMail(StockMove stockMove, Template template)
    throws AxelorException {
  sendMailForStockMove(stockMove, template);
}

protected void processBackorderLine(StockMoveLine stockMoveLine, StockMove newStockMove)
    throws AxelorException {
  if (stockMoveLine.getQty().compareTo(stockMoveLine.getRealQty()) <= 0) {
    return;
  }
  StockMoveLine newStockMoveLine = copySplittedStockMoveLine(stockMoveLine);
  newStockMove.addStockMoveLineListItem(newStockMoveLine);

  Product product = newStockMoveLine.getProduct();
  if (product != null) {
    TrackingNumberConfiguration trackingNumberConfiguration =
        (TrackingNumberConfiguration)
            productCompanyService.get(
                product, "trackingNumberConfiguration", newStockMove.getCompany());

    newStockMoveLine.setTrackingNumber(null);
    stockMoveLineService.assignOrGenerateTrackingNumber(
        newStockMoveLine,
        newStockMove,
        product,
        trackingNumberConfiguration,
        newStockMove.getTypeSelect() == StockMoveRepository.TYPE_OUTGOING
            ? StockMoveLineService.TYPE_SALES
            : StockMoveLineService.TYPE_PURCHASES);
  }
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void cancel(StockMove stockMove, CancelReason cancelReason) throws AxelorException {
  List<Integer> authorizedStatus = new ArrayList<>();
  authorizedStatus.add(StockMoveRepository.STATUS_PLANNED);
  authorizedStatus.add(StockMoveRepository.STATUS_REALIZED);
  if (stockMove.getStatusSelect() == null
      || !authorizedStatus.contains(stockMove.getStatusSelect())) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(StockExceptionMessage.STOCK_MOVE_CANCEL_WRONG_STATUS));
  }
  applyCancelReason(stockMove, cancelReason);
  cancel(stockMove);
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void cancel(StockMove stockMove) throws AxelorException {
  LOG.debug("Stock move cancel : {} ", stockMove.getStockMoveSeq());
  checkReversionStatus(stockMove);
  int initialStatus = stockMove.getStatusSelect();
  setCancelStatus(stockMove);

  if (initialStatus == StockMoveRepository.STATUS_PLANNED) {
    stockMoveLineService.updateLocations(
        initialStatus,
        StockMoveRepository.STATUS_CANCELED,
        getPlannedStockMoveLineIds(stockMove, false),
        stockMove.getEstimatedDate(),
        false,
        false);
  } else {
    stockMoveLineService.updateLocations(
        initialStatus,
        StockMoveRepository.STATUS_CANCELED,
        stockMove.getStockMoveLineList().stream()
            .map(StockMoveLine::getId)
            .collect(Collectors.toSet()),
        stockMove.getEstimatedDate(),
        true,
        true);
    stockMove.setRealDate(appBaseService.getTodayDate(stockMove.getCompany()));
    Set<Long> productIds =
        stockMove.getStockMoveLineList().stream()
            .map(StockMoveLine::getProduct)
            .filter(p -> p != null)
            .map(Product::getId)
            .collect(Collectors.toSet());
    weightedAveragePriceService.resetAvgPriceForProducts(productIds);
  }

  clearPlannedStockMoveLine(stockMove, false);
  if (stockMove.getTypeSelect() == StockMoveRepository.TYPE_INCOMING
      && initialStatus == StockMoveRepository.STATUS_REALIZED) {
    partnerProductQualityRatingService.undoCalculation(stockMove);
  }
}

@Override
public void checkReversionStatus(StockMove stockMove) throws AxelorException {
  if (stockMove == null || stockMove.getId() == null) {
    return;
  }
  List<StockMove> reversionStockMoveList =
      stockMoveRepo
          .all()
          .filter(
              "self.reversionOriginStockMove.id = :stockMoveId"
                  + " AND self.statusSelect IN (:planned, :realized)")
          .bind("stockMoveId", stockMove.getId())
          .bind("planned", StockMoveRepository.STATUS_PLANNED)
          .bind("realized", StockMoveRepository.STATUS_REALIZED)
          .order("stockMoveSeq")
          .fetch();
  if (reversionStockMoveList.isEmpty()) {
    return;
  }
  throw new AxelorException(
      stockMove,
      TraceBackRepository.CATEGORY_INCONSISTENCY,
      String.format(
          I18n.get(StockExceptionMessage.STOCK_MOVE_CANCEL_WRONG_REVERSION_STATUS),
          stockMove.getStockMoveSeq(),
          reversionStockMoveList.stream()
              .map(StockMove::getStockMoveSeq)
              .collect(Collectors.joining(", "))));
}

protected void setCancelStatus(StockMove stockMove) {
  stockMove.setStatusSelect(StockMoveRepository.STATUS_CANCELED);
  stockMoveRepo.save(stockMove);
}

protected StockMoveLine createSplitStockMoveLine(
    StockMove originalStockMove,
    StockMoveLine originalStockMoveLine,
    StockMoveLine modifiedStockMoveLine) {

  StockMoveLine newStockMoveLine = stockMoveLineRepo.copy(originalStockMoveLine, false);
  BigDecimal netMass = originalStockMoveLine.getNetMass();
  BigDecimal qty = modifiedStockMoveLine.getQty();
  newStockMoveLine.setQty(qty);
  newStockMoveLine.setRealQty(qty);
  newStockMoveLine.setTotalNetMass(netMass.multiply(qty));
  newStockMoveLine.setUnitPriceUntaxed(modifiedStockMoveLine.getUnitPriceUntaxed());

  // Update quantity in original stock move.
  // If the remaining quantity is 0, remove the stock move line
  BigDecimal remainingQty = originalStockMoveLine.getQty().subtract(qty);
  if (BigDecimal.ZERO.compareTo(remainingQty) == 0) {
    // Remove the stock move line
    originalStockMove.removeStockMoveLineListItem(originalStockMoveLine);
  } else {
    originalStockMoveLine.setQty(remainingQty);
    originalStockMoveLine.setRealQty(remainingQty);
    originalStockMoveLine.setTotalNetMass(netMass.multiply(remainingQty));
  }
  TrackingNumber trackingNumber = originalStockMoveLine.getTrackingNumber();
  if (trackingNumber != null) {
    trackingNumber.setOriginStockMoveLine(newStockMoveLine);
  }

  return newStockMoveLine;
}

@Transactional(rollbackOn = {Exception.class})
protected void applyCancelReason(StockMove stockMove, CancelReason cancelReason)
    throws AxelorException {
  if (cancelReason == null) {
    throw new AxelorException(
        stockMove,
        TraceBackRepository.CATEGORY_MISSING_FIELD,
        I18n.get(StockExceptionMessage.CANCEL_REASON_MISSING));
  }
  if (!StockMove.class.getCanonicalName().equals(cancelReason.getApplicationType())) {
    throw new AxelorException(
        stockMove,
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(StockExceptionMessage.CANCEL_REASON_BAD_TYPE));
  }
  stockMove.setCancelReason(cancelReason);
}

@Override
public void setAvailableStatus(StockMove stockMove) throws AxelorException {
  List<StockMoveLine> stockMoveLineList = stockMove.getStockMoveLineList();
  if (stockMoveLineList == null) {
    stockMove.setAvailableStatusSelect(null);
    return;
  }

  for (StockMoveLine stockMoveLine : stockMoveLineList) {
    stockMoveLineService.setAvailableStatus(stockMoveLine, stockMove);
  }

  setAvailableStatusSelectFromStockMoveLines(stockMove);
}

@Override
public void setAvailableStatusSelect(StockMove stockMove) throws AxelorException {
  if (stockMove == null || stockMove.getStockMoveLineList() == null) {
    return;
  }

  for (StockMoveLine stockMoveLine : stockMove.getStockMoveLineList()) {
    if (stockMoveLine == null || mustIgnoreForAvailableStatusSelect(stockMoveLine)) {
      continue;
    }

    stockMoveLineService.updateAvailableQty(stockMoveLine, stockMoveLine.getFromStockLocation());
  }
  setAvailableStatusSelectFromStockMoveLines(stockMove);
}

protected void setAvailableStatusSelectFromStockMoveLines(StockMove stockMove) {
  int available = 0;
  int availableForProduct = 0;
  int missing = 0;

  for (StockMoveLine stockMoveLine : stockMove.getStockMoveLineList()) {
    if (stockMoveLine == null || mustIgnoreForAvailableStatusSelect(stockMoveLine)) {
      continue;
    }

    Product product = stockMoveLine.getProduct();
    BigDecimal qty = stockMoveLine.getQty();

    if (qty == null) {
      continue;
    }

    if (stockMoveLine.getAvailableQty().compareTo(stockMoveLine.getRealQty()) >= 0
        || product != null && !product.getStockManaged()) {
      available++;
    } else if (stockMoveLine.getAvailableQtyForProduct().compareTo(stockMoveLine.getRealQty())
        >= 0) {
      availableForProduct++;
    } else if (stockMoveLine.getAvailableQty().compareTo(stockMoveLine.getRealQty()) < 0
        && stockMoveLine.getAvailableQtyForProduct().compareTo(stockMoveLine.getRealQty()) < 0) {
      missing++;
    }
  }

  if ((available > 0 || availableForProduct > 0) && missing == 0) {
    stockMove.setAvailableStatusSelect(StockMoveRepository.STATUS_AVAILABLE);
  } else if ((available > 0 || availableForProduct > 0) && missing > 0) {
    stockMove.setAvailableStatusSelect(StockMoveRepository.STATUS_PARTIALLY_AVAILABLE);
  } else if (available == 0 && availableForProduct == 0 && missing > 0) {
    stockMove.setAvailableStatusSelect(StockMoveRepository.STATUS_UNAVAILABLE);
  } else {
    stockMove.setAvailableStatusSelect(null);
  }
}

@Override
public void setMergedStatus(StockMove stockMove) {
  stockMove.setStatusSelect(StockMoveRepository.STATUS_MERGED);
}

def validate(self):
	if self._action == "submit" and not self.driver:
		frappe.throw(_("A driver must be set to submit."))

	if self._action == "submit":
		self.validate_delivery_note_not_draft()
	self.validate_delivery_notes_not_on_other_trips()
	self.validate_stop_addresses()
	self.validate_stop_contacts()

def on_cancel(self):
	self.update_status()
	self.update_delivery_notes(delete=True)

def validate_stop_addresses(self):
	for stop in self.delivery_stops:
		if stop.address and not stop.customer_address:
			stop.customer_address = get_address_display(frappe.get_doc("Address", stop.address).as_dict())

def validate_stop_contacts(self):
	stops = [stop for stop in self.delivery_stops if stop.contact and stop.customer]
	if not stops:
		return

	dynamic_link = frappe.qb.DocType("Dynamic Link")
	contact_customers = set(
		frappe.qb.from_(dynamic_link)
		.select(dynamic_link.parent, dynamic_link.link_name)
		.where(
			(dynamic_link.parenttype == "Contact")
			& (dynamic_link.link_doctype == "Customer")
			& dynamic_link.parent.isin({stop.contact for stop in stops})
		)
		.run()
	)
	for stop in stops:
		if (stop.contact, stop.customer) not in contact_customers:
			frappe.throw(
				_("Row #{0}: Contact {1} does not belong to Customer {2}").format(
					stop.idx, frappe.bold(stop.contact), frappe.bold(stop.customer)
				)
			)

def validate_delivery_note_not_draft(self):
	delivery_notes = list(set(stop.delivery_note for stop in self.delivery_stops if stop.delivery_note))
	draft_delivery_notes = frappe.get_all(
		"Delivery Note",
		{"docstatus": 0, "name": ["in", delivery_notes]},
		pluck="name",
	)
	if draft_delivery_notes:
		frappe.throw(
			_(
				"Delivery Notes should not be in draft state when submitting a Delivery Trip. The following Delivery Notes are still in draft state: {0}. Please submit them first."
			).format(", ".join(draft_delivery_notes))
		)

def validate_delivery_notes_not_on_other_trips(self):
	delivery_notes = {stop.delivery_note for stop in self.delivery_stops if stop.delivery_note}
	if not delivery_notes:
		return

	delivery_note = frappe.qb.DocType("Delivery Note")
	notes = (
		frappe.qb.from_(delivery_note)
		.select(delivery_note.name, delivery_note.delivery_trip, delivery_note.company)
		.where(delivery_note.name.isin(delivery_notes))
		.for_update()
		.run(as_dict=True)
	)
	if other_company := [d.name for d in notes if self.company and d.company != self.company]:
		frappe.throw(
			_("Delivery Notes {0} do not belong to Company {1}").format(
				", ".join(other_company), frappe.bold(self.company)
			)
		)

	other_trips = {d.delivery_trip for d in notes if d.delivery_trip and d.delivery_trip != self.name}
	open_trips = other_trips and set(
		frappe.get_all(
			"Delivery Trip",
			filters={"name": ("in", list(other_trips)), "docstatus": ("<", 2)},
			pluck="name",
		)
	)
	if linked := [d for d in notes if open_trips and d.delivery_trip in open_trips]:
		frappe.throw(
			_("Delivery Notes are already on another Delivery Trip: {0}").format(
				", ".join(f"{d.name} ({d.delivery_trip})" for d in linked)
			)
		)

def update_status(self):
	status = {0: "Draft", 1: "Scheduled", 2: "Cancelled"}[self.docstatus]

	if self.docstatus == 1:
		visited_stops = [stop.visited for stop in self.delivery_stops]
		if all(visited_stops):
			status = "Completed"
		elif any(visited_stops):
			status = "In Transit"

	self.db_set("status", status)

